-- Generated by tools/reference/import-catalogs.cs from pinned source files: change that script, not this file.
-- Each drug product's ingredients (RxNorm), each ingredient's FDA Established Pharmacologic Classes, and the classes that cross-react (curated, each row citing its source).
-- Applied as ehr_owner after db/policies; safe to run again. Sources, versions, licenses and attribution:
-- docs/expansion/reference-data.md. The rows are COPY blocks, as pg_dump writes them: psql loads the file as it
-- stands, and the tests' database through tests/Ehr.Testing/ReferenceData.cs. Tab-separated; \N is a null.
BEGIN;
CREATE TEMPORARY TABLE incoming_drug_ingredients (product_code text, ingredient_code text) ON COMMIT DROP;
SELECT product_code, ingredient_code FROM incoming_drug_ingredients
ON CONFLICT (product_code, ingredient_code) DO NOTHING;
DELETE FROM ehr.drug_ingredients t
WHERE NOT EXISTS (SELECT 1 FROM incoming_drug_ingredients i WHERE i.product_code = t.product_code AND i.ingredient_code = t.ingredient_code);
CREATE TEMPORARY TABLE incoming_drug_classes (ingredient_code text, class_name text) ON COMMIT DROP;
SELECT ingredient_code, class_name FROM incoming_drug_classes
ON CONFLICT (ingredient_code, class_name) DO NOTHING;
DELETE FROM ehr.drug_classes t
WHERE NOT EXISTS (SELECT 1 FROM incoming_drug_classes i WHERE i.ingredient_code = t.ingredient_code AND i.class_name = t.class_name);
CREATE TEMPORARY TABLE incoming_drug_class_cross_reactions (class_a text, class_b text, note text, source text) ON COMMIT DROP;
SELECT class_a, class_b, note, source FROM incoming_drug_class_cross_reactions
ON CONFLICT (class_a, class_b) DO UPDATE
    SET note = EXCLUDED.note, source = EXCLUDED.source
    WHERE (drug_class_cross_reactions.note, drug_class_cross_reactions.source)
        IS DISTINCT FROM (EXCLUDED.note, EXCLUDED.source);
DELETE FROM ehr.drug_class_cross_reactions t
WHERE NOT EXISTS (SELECT 1 FROM incoming_drug_class_cross_reactions i WHERE i.class_a = t.class_a AND i.class_b = t.class_b);
COMMIT;
